∀ {K : Type u_1} [inst : Field K] {ι : Type u_2} {κ : Type u_3}
  [inst_1 : Fintype ι] [inst_2 : DecidableEq ι] (E : (ι → K) →ₗ[K] κ → K) (i : κ) (y : ι → K),
  (MvPolynomial.eval y) (QuaternaryQuadraticForms.coordinatePolynomial E i) = E y i

∀ {K : Type u_1} [inst : Field K] {ι : Type u_2}
  {κ : Type u_3} [inst_1 : Fintype ι] [inst_2 : DecidableEq ι] (E : (ι → K) →ₗ[K] κ → K) (i : κ),
  (QuaternaryQuadraticForms.coordinatePolynomial E i).IsHomogeneous 1

∀ {K : Type u_1} [inst : Field K] {N : ℕ}
  (F G : MvPolynomial (Fin N) K),
  QuaternaryQuadraticForms.ProjectiveIntersectionTransverseRank F G → (∃ x, x ≠ 0 ∧ (MvPolynomial.eval x) F = 0) → G ≠ 0

∀ {R : Type u_1} [inst : CommSemiring R] {N d : ℕ}
  (c : QuaternaryQuadraticForms.HomogeneousMonomial N d → R),
  (QuaternaryQuadraticForms.homogeneousForm c).IsHomogeneous d

∀ {R : Type u_1} [inst : CommSemiring R] {N d : ℕ}
  (c : QuaternaryQuadraticForms.HomogeneousMonomial N d → R) (m : QuaternaryQuadraticForms.HomogeneousMonomial N d),
  MvPolynomial.coeff (↑m) (QuaternaryQuadraticForms.homogeneousForm c) = c m

∀ {R : Type u_1} [inst : CommSemiring R] {N d : ℕ}
  (c : QuaternaryQuadraticForms.HomogeneousMonomial N d → R) (m : Fin N →₀ ℕ),
  MvPolynomial.coeff m (QuaternaryQuadraticForms.homogeneousForm c) = if h : m.degree = d then c ⟨m, h⟩ else 0

∀ {R : Type u_1} [inst : CommSemiring R] {N d : ℕ}
  (P : MvPolynomial (Fin N) R),
  P.IsHomogeneous d → (QuaternaryQuadraticForms.homogeneousForm fun m => MvPolynomial.coeff (↑m) P) = P

∀ {K : Type u_1} [inst : Field K] {n : ℕ}
  (G : MvPolynomial (Fin 4) K) (P : MvPolynomial (QuaternaryQuadraticForms.ExceptionalPlaneParameter n) ℤ),
  (QuaternaryQuadraticForms.specializePlaneResultant G P).totalDegree ≤ P.totalDegree

∀ (q₁ q₂ c₁ c₂ : ℕ) (A : Matrix (Fin 4) (Fin 4) ℤ)
  (x₁ x₂ u : Fin 4 → ℤ) (a₁ a₂ : ℤ),
  ↑q₁ ∣ x₁ ⬝ᵥ A.mulVec x₁ →
    ↑q₂ ∣ x₂ ⬝ᵥ A.mulVec x₂ →
      have n₁ := q₁ * c₁;
      have n₂ := q₂ * c₂;
      have x := ↑n₂ • x₁ + ↑n₁ • x₂;
      ↑((↑c₂ * a₁ + ↑c₁ * a₂) * x ⬝ᵥ A.mulVec x + u ⬝ᵥ x) =
        ↑(↑n₂ * (↑c₂ * ↑n₂ * a₁ * x₁ ⬝ᵥ A.mulVec x₁ + u ⬝ᵥ x₁) + ↑n₁ * (↑c₁ * ↑n₁ * a₂ * x₂ ⬝ᵥ A.mulVec x₂ + u ⬝ᵥ x₂))

∀ (q₁ q₂ c₁ c₂ : ℕ) [inst : NeZero q₁] [inst_1 : NeZero q₂]
  [inst_2 : NeZero c₁] [inst_3 : NeZero c₂] (A : Matrix (Fin 4) (Fin 4) ℤ) (x₁ x₂ u : Fin 4 → ℤ) (a₁ a₂ : ℤ),
  ↑q₁ ∣ x₁ ⬝ᵥ A.mulVec x₁ →
    ↑q₂ ∣ x₂ ⬝ᵥ A.mulVec x₂ →
      let n₁ := q₁ * c₁;
      let n₂ := q₂ * c₂;
      have x := ↑n₂ • x₁ + ↑n₁ • x₂;
      ZMod.stdAddChar ↑((↑c₂ * a₁ + ↑c₁ * a₂) * x ⬝ᵥ A.mulVec x + u ⬝ᵥ x) =
        ZMod.stdAddChar ↑(↑c₂ * ↑n₂ * a₁ * x₁ ⬝ᵥ A.mulVec x₁ + u ⬝ᵥ x₁) *
          ZMod.stdAddChar ↑(↑c₁ * ↑n₁ * a₂ * x₂ ⬝ᵥ A.mulVec x₂ + u ⬝ᵥ x₂)
